const sourceAtomCountsForSources = `-- name: SourceAtomCountsForSources :many
SELECT s.source_id AS source_id, count(DISTINCT a.id) AS count
FROM atom_sources s
JOIN atoms a ON a.id = s.atom_id
WHERE s.source_id IN (/*SLICE:ids*/?)
GROUP BY s.source_id
`

type SourceAtomCountsForSourcesRow struct {
	SourceID ulid.ULID `json:"source_id"`
	Count    int64     `json:"count"`
}

// Claim counts for EXACTLY these sources. One list page must not pay for the GROUP BY over every
// provenance row in the index.
func (q *Queries) SourceAtomCountsForSources(ctx context.Context, ids []ulid.ULID) ([]SourceAtomCountsForSourcesRow, error) {
	query := sourceAtomCountsForSources
	var queryParams []interface{}
	if len(ids) > 0 {
		for _, v := range ids {
			queryParams = append(queryParams, v)
		}
		query = strings.Replace(query, "/*SLICE:ids*/?", strings.Repeat(",?", len(ids))[1:], 1)
	} else {
		query = strings.Replace(query, "/*SLICE:ids*/?", "NULL", 1)
	}
	rows, err := q.db.QueryContext(ctx, query, queryParams...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []SourceAtomCountsForSourcesRow
	for rows.Next() {
		var i SourceAtomCountsForSourcesRow
		if err := rows.Scan(&i.SourceID, &i.Count); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

